item(d,7,'Tracking cung cấp thêm gì cho prediction/planning so với detection từng frame độc lập?', ['ID ổn định, vận tốc và lịch sử quỹ đạo','Chỉ class và score của một frame không có lịch sử','Chỉ box lớn hơn để chứa mọi chuyển động có thể xảy ra'],'a','Liên kết qua thời gian tạo trạng thái và lịch sử cần cho dự đoán chuyển động.')
item(d,8,'Online tracking khác offline tracking ở dữ liệu thời gian được phép sử dụng thế nào?', ['Online chỉ dùng hiện tại/quá khứ; offline có thể dùng frame tương lai để sửa liên kết','Online luôn dùng toàn video còn offline chỉ dùng frame đầu','Cả hai bắt buộc cho cùng kết quả vì dùng cùng detections'],'a','Quyền nhìn tương lai tạo khác biệt quan trọng cho xử lý occlusion và sửa ID.')
item(d,10,'Trong tracking-by-detection, association nối hai tập nào?', ['Track đã predict với detections hiện tại','Chỉ detections trong cùng một frame với nhau','Ground-truth test với labels train để học model'],'a','Predict ước lượng vị trí track; association chọn detections phù hợp để update.')
item(d,11,'Khi tạm mất detection, bước predict của Kalman thường làm gì với trạng thái và độ bất định?', ['Ngoại suy theo motion model và tăng bất định','Giữ nguyên uncertainty dù không có phép đo mới','Đặt track chính xác tuyệt đối tại detection cuối'],'a','Thiếu measurement làm dự đoán phụ thuộc model hơn và không chắc chắn tích lũy.')
item(d,12,'Một vật mất detection 18 frames với track_buffer 30 có thể giữ cùng ID khi trở lại vì sao?', ['Track Lost chưa bị Removed và có thể match lại','Mỗi frame mất detection bắt buộc tạo ID mới','track_buffer là số detection cần để khởi tạo track'],'a','Buffer cho phép giữ track tạm mất thay vì xóa ngay.',level='apply')
item(d,15,'Những tín hiệu nào có thể phối hợp trong association cost? (Chọn tất cả đáp án đúng.)',['Hình học box','Motion dự đoán và uncertainty','Appearance embedding','Chỉ class label, không cần phân biệt từng instance'],['a','b','c'],'Nhiều nguồn bổ sung nhau khi một tín hiệu thiếu phân biệt hoặc bị che khuất.')
item(d,16,'Hai box mỗi box diện tích 12 và phần giao 4 có IoU bao nhiêu?', ['0,2','1/3 vì chia giao cho một box','0,5 vì bỏ phần giao khi tính union'],'a','Union=12+12−4=20, IoU=4/20=0,2.',level='apply')
item(d,16,'IoU-only association dễ thất bại ở FPS thấp với vật đi nhanh vì sao?', ['Cùng vật nhưng box qua hai frames không còn chồng nhau','IoU có thể nhận diện ngoại hình dù box không giao','IoU tự ước lượng vận tốc từ một box'],'a','Không overlap làm IoU bằng 0 dù hai detections cùng đối tượng; cần tín hiệu bổ sung.')
item(d,18,'Mahalanobis gating có lợi gì so với dùng khoảng cách Euclidean cố định?', ['Chuẩn hóa sai lệch theo covariance để phản ánh hướng chắc/chưa chắc của prediction','Coi mọi hướng có cùng bất định bất kể Kalman estimate','Thay hoàn toàn motion model bằng appearance embedding'],'a','Vùng chấp nhận có thể hẹp ở hướng chắc và rộng ở hướng bất định.')
item(d,19,'Appearance embeddings có hạn chế nào khi hai người mặc đồng phục giống nhau?', ['Đặc trưng ngoại hình có thể thiếu phân biệt nên vẫn nhầm ID','Embedding chắc chắn phân biệt mọi instance nếu cùng class','Motion information trở nên không còn hữu ích'],'a','Re-ID là một tín hiệu có failure modes, không bảo đảm danh tính trong mọi cảnh.')
item(d,25,'SORT phù hợp hơn với điều kiện nào khi ưu tiên tốc độ?', ['Camera tĩnh, cảnh thưa và ít occlusion dài','Nhiều người giống nhau che khuất lâu với camera chuyển động mạnh','Cần cross-camera re-identification bằng appearance'],'a','SORT nhẹ nhờ motion/IoU nhưng không có Re-ID để cứu các tình huống khó về danh tính.')
item(d,28,'OC-SORT nhắm vào lỗi nào của Kalman khi vật bị che?', ['Vật đổi hướng trong lúc khuất khiến ngoại suy vận tốc cũ trôi xa','Hai crop có cùng màu khiến appearance vector trùng nhau','Detector luôn gán sai class do ontology mơ hồ'],'a','Quan sát trước/sau và virtual trajectory giúp sửa trạng thái khi motion model đã lệch.')
item(d,29,'Global Motion Compensation trong BoT-SORT nhằm tách điều gì?', ['Chuyển động camera khỏi chuyển động của vật','Mọi khác biệt appearance khỏi ảnh màu','Thời gian inference khỏi thời gian annotation'],'a','Camera chuyển động làm nền/vật tĩnh cũng dịch trên ảnh; bù ego-motion giảm lệch prediction.')
item(d,35,'Tracker xuất một box ở nơi không có vật thật. Đây là loại lỗi nào?', ['False positive','False negative do bỏ sót vật thật','ID switch giữa hai track đúng vị trí'],'a','FP là box dư; FN là thiếu box cho vật tồn tại.')
item(d,37,'Với GT=1000, FN=100, FP=50, IDSW=30, MOTA bằng bao nhiêu?', ['82%','85% vì bỏ qua ID switches','18% vì báo tỷ lệ lỗi thay vì điểm còn lại'],'a','MOTA=1−(100+50+30)/1000=0,82.',level='apply')
item(d,38,'Box đúng vị trí nhưng một người bị chia thành hai IDs trong video ảnh hưởng metric identity vì sao?', ['Ghép danh tính toàn video chỉ chọn một predicted ID tốt nhất, nên đoạn ID khác vẫn bị phạt','Đúng box từng frame làm mọi metric identity đạt tối đa','Chỉ FP/FN box mới ảnh hưởng, đổi ID không có ý nghĩa'],'a','IDF1 xem tính nhất quán danh tính qua chuỗi, khác chỉ đếm phát hiện hình học.')
d='p2-t4-d08'
item(d,3,'Vì sao một pixel đơn lẻ chưa xác định duy nhất vị trí 3D?', ['Nhiều điểm dọc cùng tia nhìn có thể chiếu vào cùng pixel','Một pixel luôn chứa trực tiếp khoảng cách mét','Ma trận K tự cung cấp depth cho mọi vật'],'a','Projection mất chiều sâu; cần thêm thông tin hình học, nhiều góc nhìn hoặc sensor đo depth.')
item(d,5,'Camera intrinsic K và extrinsics R,t mô tả hai loại thông tin nào?', ['Đặc tính phép chiếu của camera và pose tương đối của camera','K là pose trên xe còn R,t là class của vật','Cả hai đều là tham số thay đổi theo từng object detection'],'a','Intrinsics gồm focal length/principal point; extrinsics nối hệ tọa độ sensor với hệ tham chiếu.')
item(d,6,'Một box 3D kiểu xe thường cần nhóm tham số nào? (Chọn tất cả đáp án đúng.)',['Tâm 3D','Kích thước rộng/dài/cao','Yaw quanh trục đứng','Chỉ bốn cạnh box 2D là đủ xác định mọi tham số'],['a','b','c'],'Vị trí, kích thước và hướng mô tả box 3D, khác hình chiếu 2D có depth ambiguity.')
item(d,7,'Ước lượng khoảng cách từ chân vật trên mặt đường dễ nhạy gần đường chân trời vì sao?', ['Sai số rất nhỏ của hàng pixel có thể tạo sai số depth lớn','Khoảng cách luôn không phụ thuộc vị trí chân vật','Giả định mặt đường phẳng trở nên đúng tuyệt đối ở xa'],'a','Hình học ground-contact nhạy ở xa và còn bị ảnh hưởng bởi dốc/dao động camera.')
item(d,9,'Một detector monocular 3D cần depth head vì lý do nào?', ['Tọa độ tâm trên ảnh chưa cho vị trí dọc tia nhìn','Depth chỉ giúp chọn tên class mà không ảnh hưởng vị trí','Box 2D tự xác định khoảng cách không cần giả định nào'],'a','Depth cùng pixel và calibration mới cho phép khôi phục vị trí 3D.')
item(d,12,'NDS tổng hợp thêm gì ngoài khả năng tìm đúng object bằng mAP?', ['Các sai số TP như vị trí, kích thước, hướng, vận tốc và thuộc tính','Chỉ số FPS và bộ nhớ runtime','Chỉ loss train của backbone'],'a','Detection quality cần xét chất lượng vị trí/trạng thái của các detections đúng, không chỉ AP.')
item(d,14,'BEV hữu ích cho planning bởi đặc tính nào?', ['Biểu diễn vị trí trên mặt đất với kích thước không bị phối cảnh bóp méo','Giữ vật xa nhỏ hơn để planning dùng kích thước pixel','Chỉ chứa dữ liệu một camera nên không cần hệ tọa độ chung'],'a','Không gian BEV chung dễ nối nhiều cameras/sensors và các task quanh bản đồ mặt đất.')
item(d,17,'Một object query kiểu DETR3D dùng reference point 3D để lấy ảnh feature như thế nào?', ['Chiếu điểm vào camera thấy nó rồi lấy feature tại vị trí tương ứng','Lấy cùng tọa độ pixel ở mọi camera mà không dùng calibration','Chọn ngẫu nhiên crop và coi là cùng điểm 3D'],'a','Geometry xác định camera/pixel liên quan; query được cập nhật qua các decoder layers.')
item(d,18,'Temporal BEV fusion cần xử lý ego-motion trước khi ghép frames vì sao?', ['Đưa biểu diễn cũ về cùng hệ vị trí với hiện tại','Để coi mọi vật dịch trên ảnh đều chuyển động thật','Để thay depth bằng số frame đã qua'],'a','Không align chuyển động bản thân xe sẽ trộn feature của các vị trí vật lý khác nhau.')
item(d,18,'Occupancy khác chỉ dự đoán boxes ở điểm nào?', ['Dự đoán trạng thái trống/đặc theo voxel, phù hợp hình dạng bất kỳ','Chỉ giữ vật nằm trong một danh sách boxes cố định','Chỉ dự đoán class mà không xét vùng không gian bị chiếm'],'a','Biểu diễn không gian bị chiếm giúp xử lý cả vật không khớp hình hộp/class quen thuộc.')
item(d,25,'Một xe chuyển động vuông góc tia nhìn radar có Doppler gần 0. Kết luận nào phù hợp?', ['Thành phần vận tốc radial nhỏ, không chứng minh xe đứng yên','Toàn bộ vector vận tốc của xe bằng 0','Radar đã đo được đầy đủ vận tốc ngang'],'a','Doppler phản ánh projection vận tốc lên tia nhìn, không phải độ lớn vận tốc toàn phần.')
item(d,26,'Fusion thấy vật chuyển động bị lệch giữa camera và LiDAR dù pose tĩnh khớp. Nên kiểm tra thêm gì?', ['Đồng bộ timestamp và bù chuyển động','Chỉ class ontology của detector','Chỉ kích thước feature vector bất kể thời gian'],'a','Temporal misalignment gây lệch vị trí của vật đang đi dù spatial calibration có thể đúng.')
item(d,28,'Sau khi tháo và lắp camera ở góc khác, tham số nào cần được xem xét lại trực tiếp?', ['Extrinsics so với thân xe','Chỉ class labels của dataset','Chỉ số layers của detection head'],'a','Vị trí/góc lắp thay đổi phép biến đổi tọa độ sensor→ego.')
item(d,29,'Timestamp matching nên xử lý hai mẫu quá xa nhau về thời gian thế nào?', ['Loại cặp vượt cửa sổ dung sai hoặc dùng cơ chế bù phù hợp','Ghép theo thứ tự đến bất kể timestamp','Giữ mọi cặp vì cùng sequence là đủ đồng thời'],'a','Fusion cần phép đo đại diện cùng thời điểm; timestamp gần nhất vẫn phải nằm trong mức lệch chấp nhận.')
item(d,32,'Mid fusion ghép các sensor ở mức nào?', ['Features sau backbone riêng, trước khi ra boxes cuối','Dữ liệu raw trước mọi backbone','Boxes cuối từ hai detectors độc lập'],'a','Mid fusion giữ xử lý riêng từng sensor rồi kết hợp biểu diễn trung gian.')
item(d,33,'Late fusion có thể khó cứu một vật mà cả hai detector đều bỏ qua vì sao?', ['Thông tin yếu đã bị loại trước khi tới bước ghép boxes','Nó vẫn có đầy đủ mọi raw features nên không mất thông tin','Chỉ vì bắt buộc mọi sensor dùng cùng backbone'],'a','Tính module hóa đi cùng mất khả năng khai thác tín hiệu raw/subthreshold đã bị nhánh riêng bỏ qua.')
