item(d,15,'Vì sao Bronze nên giữ bản gốc append-only kèm checksum và nguồn?', ['Cho phép tái chạy các lớp xử lý và truy nguồn dữ liệu','Để sửa trực tiếp bản gốc mỗi lần làm sạch','Để không cần lưu metadata của các lần ingest'],'a','Raw data bảo toàn làm nền cho reproducibility và điều tra lỗi ở các bước sau.')
item(d,18,'Bảng metadata giữ URI video; xóa một dòng bảng chưa chắc xóa file. Cần quản lý thêm gì?', ['File mồ côi và tính toàn vẹn nội dung qua checksum','Coi mọi file đã tự biến mất cùng dòng bảng','Bỏ object storage để nhúng toàn video vào mọi truy vấn metadata'],'a','Metadata và object có vòng đời riêng; con trỏ không tự quản toàn bộ lifecycle của blob.')
item(d,19,'Parquet giúp truy vấn chỉ hai cột của một metadata table theo cách nào?', ['Đọc các cột cần thay vì toàn bộ mọi cột','Decode toàn bộ video trước khi biết hai cột','Bắt buộc đọc tất cả rows và mọi trường dưới dạng ảnh'],'a','Lưu theo cột giảm I/O cho column projection và hỗ trợ nén dữ liệu cùng kiểu.')
item(d,20,'Time travel của open table format dựa trên cơ chế nào?', ['Commit xác định tập files tạo một snapshot của bảng','Sửa đè mọi Parquet file cũ mà không giữ lịch sử','Chỉ đổi tên thư mục thành v1/v2 không lưu danh sách files'],'a','Snapshot/commit cho phép tái dựng trạng thái bảng qua các phiên bản files.')
item(d,21,'Trong Medallion, Silver và Gold nên có quan hệ gì với Bronze?', ['Có thể sinh lại từ raw Bronze qua bước xử lý được xác định','Thay thế bản gốc bằng dữ liệu đã làm sạch để tiết kiệm lịch sử','Là ba tên cho cùng dữ liệu không có biến đổi'],'a','Bronze bảo toàn nguồn; các lớp sau lọc/làm sạch và tạo dataset phục vụ nhu cầu cụ thể.')
item(d,24,'Pipeline embedding video có GPU nhàn nhưng decode CPU nghẽn. Hướng xử lý nào khớp bottleneck?', ['Tối ưu/song song hoặc chuyển decode phù hợp sang GPU','Chỉ tăng batch model dù input chưa được decode kịp','Chỉ tăng số labels mà không thay throughput decode'],'a','Cần tối ưu bước cấp frames trước khi tăng năng lực inference không được nuôi dữ liệu.')
item(d,25,'Backfill trong orchestration nghĩa là gì?', ['Chạy bù xử lý cho khoảng thời gian dữ liệu cũ','Chỉ chạy task tiếp theo ngay khi có event mới','Xóa mọi partition cũ để tạo dataset mới từ đầu'],'a','DAG và trạng thái cho phép điều phối lịch, retry và xử lý lại phần lịch sử cần thiết.')
item(d,26,'Retry một partition đã ghi một phần nên tránh append không kiểm soát vì sao?', ['Có thể nhân đôi rows và làm kết quả không idempotent','Append tự nhận ra mọi rows đã có mà không cần khóa','Ghi thêm luôn tương đương thay partition đối với cùng input'],'a','Cùng input chạy lại phải cho cùng kết quả; overwrite/replace partition có thể tránh duplication.')
item(d,27,'Những checks nào phù hợp quality gate cho dữ liệu thị giác? (Chọn tất cả đáp án đúng.)',['Schema/null/range/freshness và duplicates','Khung đen/mờ','Box nằm ngoài ảnh','Chỉ kiểm job có exit code 0'],['a','b','c'],'Pipeline chạy thành công chưa chứng minh dữ liệu hợp lệ cả ở bảng và nội dung ảnh.')
item(d,28,'Cùng bộ bốn số box có thể hợp lệ nhưng sai hình học khi đổi tool vì sao?', ['Khác quy ước xyxy/xywh, gốc/tâm hoặc chuẩn hóa','Mọi định dạng box dùng cùng convention mặc định','Chỉ class ID mới cần chuyển đổi, tọa độ không đổi'],'a','Kiểm type/range chưa đủ; cần rõ convention và vẽ thử sau chuyển đổi.')
item(d,29,'Lineage cho model cần trả lời câu hỏi nào?', ['Model được tạo từ dataset, bước xử lý và nguồn nào','Chỉ model đang đạt accuracy bao nhiêu','Chỉ ai tải model xuống gần nhất'],'a','Dấu vết nguồn gốc giúp tái lập và truy ngược lỗi từ model về dữ liệu.')
item(d,42,'Hai annotators gán nhãn khác nhau cho người dắt xe đạp. Bước giải quyết nền tảng là gì?', ['Kiểm guideline định nghĩa cyclist và cách tách người/xe','Chọn nhãn của người làm nhanh hơn','Trộn cả hai conventions để tăng số labels'],'a','Ground truth phụ thuộc đặc tả thống nhất; cần giải quyết định nghĩa trước khi quy lỗi cho người gán.')
item(d,46,'Vì sao labels do con người tạo vẫn cần audit mẫu độc lập?', ['Con người cũng có thể sai; quality claim cần cơ sở kiểm tra','Human labels luôn đúng nên audit chỉ đo tốc độ','Có reviewer thì không cần xác định guideline'],'a','Kiểm tra độc lập ước lượng lỗi và xác nhận chuẩn dùng đánh giá máy.')
item(d,47,'Auto-label offline có lợi thế nào so với perception online?', ['Dùng cả frames tương lai và nhiều compute hơn mà không bị cùng latency constraint','Bắt buộc chỉ xem một frame để tránh leakage trong labels','Mọi output offline đều đúng nên không cần kiểm tra'],'a','Toàn chuỗi hỗ trợ refinement qua occlusion; khác quyền thông tin của hệ thống realtime.')
item(d,54,'Routing labels theo confidence nên được thiết kế như thế nào?', ['Calibrate trên gold set, audit nhóm cao và chuyển nhóm yếu/bất đồng cho người','Dùng một threshold tùy chọn như bảo đảm đúng cho mọi domain','Tự chấp nhận toàn bộ nếu model trả score dạng số'],'a','Confidence cần calibration; phân tầng review giảm công mà vẫn kiểm soát lỗi.')
